    private const val SEP = '\n'
    private const val ALT = ' '

    private val data: String by lazy(LazyThreadSafetyMode.SYNCHRONIZED) {
        buildString {
            append(CHUNK_0)
            append(CHUNK_1)
            append(CHUNK_2)
            append(CHUNK_3)
            append(CHUNK_4)
            append(CHUNK_5)
            append(CHUNK_6)
            append(CHUNK_7)
        }
    }

    /** `offsets[i]` .. `offsets[i + 1]` is the slice of [data] holding the readings of `START + i`. */
    private val offsets: IntArray by lazy(LazyThreadSafetyMode.SYNCHRONIZED) {
        val text = data
        val result = IntArray(END - START + 1)
        var index = 0
        var offset = 0
        while (offset < text.length) {
            var next = text.indexOf(SEP, offset)
            if (next < 0) next = text.length
            result[index] = offset
            index++
            offset = next + 1
        }
        // Trailing entries point at the end of the string, i.e. an empty slice.
        while (index < result.size) {
            result[index] = text.length
            index++
        }
        result
    }

    /**
     * Readings of `char`, or an empty slice when it has no known reading.
     *
     * `table[index + 1]` is where the *next* entry starts, i.e. just past the separating
     * newline, so the slice has to stop one short of it. Reading it verbatim folds the newline
     * into the final syllable, which silently breaks every single-reading character - the ones
     * with no internal space to split on - while leaving polyphonic ones looking fine.
     */
    private fun readingsOf(char: Char): String {
        val index = char.code - START
        if (index < 0 || index >= END - START) return ""
        val table = offsets
        val start = table[index]
        val end = table[index + 1] - 1
        return if (end <= start) "" else data.substring(start, end)
    }

    /** Whether [char] contributes anything to a pinyin match. */
    fun hasReading(char: Char): Boolean = readingsOf(char).isNotEmpty()

    /**
     * True when [query] - a run of pinyin syllables - matches some substring of [text].
     *
     * `dp[i][j]` asks whether the first `i` characters of the query cover a run of characters
     * of [text] ending at `j`. A reading that consumes the whole query starts a new run; a
     * shorter one extends the run that was already in progress. Restarts are folded into the
     * same table, so this stays linear in `text.length * query.length` instead of trying every
     * start position.
     *
     * Single-character readings are accepted as initials, which is what makes an abbreviated
     * query like `jj` reach 进击.
     */
    fun matches(text: String, query: String): Boolean {
        val m = query.length
        if (m == 0) return true
        if (m < MIN_QUERY) return false

        // prev/cur hold one column of the table: index = characters of the query consumed.
        var prev = BooleanArray(m + 1)
        var cur = BooleanArray(m + 1)
        var anyCovered = false

        for (char in text) {
            val readings = readingsOf(char)
            if (readings.isEmpty()) {
                // A character with no reading breaks any run in progress.
                prev.fill(false)
                cur.fill(false)
                continue
            }

            cur.fill(false)
            // Walk the readings of this character, splitting on ALT.
            var start = 0
            while (start <= readings.length) {
                var end = readings.indexOf(ALT, start)
                if (end < 0) end = readings.length
                val length = end - start
                if (length > 0) {
                    if (length <= m) {
                        if (query.regionMatches(0, readings, start, length)) {
                            // Reading is the whole query: a run may start here.
                            cur[length] = true
                        }
                        for (i in length + 1..m) {
                            if (prev[i - length] &&
                                query.regionMatches(i - length, readings, start, length)
                            ) {
                                cur[i] = true
                            }
                        }
                    }
                    // Initials: the first letter of each reading. Kept outside the branch above
                    // on purpose - an initial is always one character, so a reading longer than
                    // the query (jin against `jj`) still has to contribute it.
                    if (m >= 2) {
                        if (query.regionMatches(0, readings, start, 1)) {
                            cur[1] = true
                        }
                        for (i in 2..m) {
                            if (prev[i - 1] && query.regionMatches(i - 1, readings, start, 1)) {
                                cur[i] = true
                            }
                        }
                    }
                }
                if (end >= readings.length) break
                start = end + 1
            }

            if (cur[m]) {
                anyCovered = true
                break
            }
            val swap = prev
            prev = cur
            cur = swap
        }

        return anyCovered
    }

    /** Below this length an all-letters query matches far too much to be useful. */
    const val MIN_QUERY = 2
}
